549:   let index = -1;
550:   let legacyAssistantDone = false;
551:   let runningTool = false;
552:   let ended = false;
553:   for (let i = 0; i < messages.length; i++) {
554:     const message = messages[i]!;
555:     if (message.kind === "user" && !message.pending && !message.steerId) {
556:       const anchor = messages[index];
557:       const timing = anchor?.kind === "user" ? anchor.turnTiming : undefined;
558:       const completed =
559:         ended ||
560:         (timing
561:           ? timing.completed === true || timing.completedAt !== undefined
562:           : legacyAssistantDone && !runningTool);
563:       const injected = message.injected === true || isSystemReminderText(message.text);
564:       if (!injected || index < 0 || completed) {
565:         index = i;
566:         legacyAssistantDone = false;
567:         runningTool = false;
568:         ended = false;
569:       }
570:     } else if (message.kind === "assistant") legacyAssistantDone = message.done;
571:     else if (
572:       message.kind === "tool" &&
573:       (message.status === "running" || message.status === "queued")
574:     )
575:       runningTool = true;
576:     else if (message.kind === "turn_end") ended = true;
577:   }
578:   const user = messages[index];
579:   if (!user || user.kind !== "user") return messages;
580:   const previous = user.turnTiming;
581:   let timing: NonNullable<UserMessage["turnTiming"]>;
582:   if (event.type === "session_started") {
583:     timing = { startedAt: validTimestamp(event.startedAt) ?? validTimestamp(timestamp) };
584:   } else if (event.type === "stream_request_start") {
585:     if (previous) return messages;
586:     timing = { startedAt: validTimestamp(user.createdAt) ?? validTimestamp(timestamp) };
587:   } else {
588:     const startedAt =
589:       validTimestamp(event.startedAt) ??
590:       validTimestamp(previous?.startedAt) ??
591:       validTimestamp(user.createdAt);
592:     const completedAt =
593:       validTimestamp(event.completedAt) ??
594:       validTimestamp(previous?.completedAt) ??
595:       validTimestamp(timestamp);
596:     timing = {
597:       startedAt,
598:       completedAt,
599:       durationMs:
600:         validTime(event.durationMs) ??
601:         previous?.durationMs ??
602:         (startedAt !== undefined && completedAt !== undefined
603:           ? Math.max(0, completedAt - startedAt)
604:           : undefined),
605:       completed: true,
606:       completedCleanly: event.reason === "completed",
607:     };
608:   }
609:   const next = messages.slice();
610:   next[index] = {
611:     ...user,
612:     ...(event.type === "session_started" && event.runId
613:       ? { sourceEventId: user.sourceEventId ?? event.runId }
614:       : {}),
615:     turnTiming: timing,
616:   };
617:   return next;
618: }

